try { const parts=await Promise.all(Array.from({length:13},async(_,i)=>{const r=await fetch(new URL(`stats-2e3f0bdaec3b-${i}.txt`,import.meta.url));if(!r.ok)throw Error('Dashboard download failed. Refresh in a minute.');return r.text();}));const data=Uint8Array.from(atob(parts.join('')),c=>c.charCodeAt(0));const source=await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('gzip'))).text();const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));await import(url);URL.revokeObjectURL(url);}catch(e){document.getElementById('status').textContent='Could not open dashboard: '+e.message;}